import unittest
from src.logic import clamp

class ClampTests(unittest.TestCase):
    def test_inside(self): self.assertEqual(clamp(5, 0, 10), 5)
    def test_low(self): self.assertEqual(clamp(-7, 0, 10), 0)
    def test_high(self): self.assertEqual(clamp(17, 0, 10), 10)
    def test_invalid(self):
        with self.assertRaises(ValueError): clamp(1, 9, 3)

