import unittest
from src.logic import parse_pairs

class PairTests(unittest.TestCase):
    def test_basic(self): self.assertEqual(parse_pairs('a=1,b=2'), {'a':'1','b':'2'})
    def test_value_equals(self): self.assertEqual(parse_pairs('token=a=b'), {'token':'a=b'})
    def test_whitespace(self): self.assertEqual(parse_pairs(' a = 1 , b= 2 '), {'a':'1','b':'2'})
    def test_empty(self): self.assertEqual(parse_pairs(''), {})
    def test_malformed(self):
        with self.assertRaises(ValueError): parse_pairs('a=1,no-equals')

